package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.UUID;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class TemporaryWorldManagerTest{@TempDir Path temp;@Test void 原本を変更せず一時コピーだけ削除する()throws Exception{MapProfile p=profile();Path original=temp.resolve("maps/a/template/level.dat");String before=Files.readString(original);TemporaryWorldManager m=manager();var w=m.create(p,"setup");Files.writeString(w.directory().resolve("changed.txt"),"x");m.delete(w);assertFalse(Files.exists(w.directory()));assertEquals(before,Files.readString(original));}@Test void 無関係ディレクトリを削除せず所有worldだけ回収する()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();var owned=m.create(p,"run");Path unrelated=temp.resolve("worlds/orushio_run_unrelated");Files.createDirectories(unrelated);Files.writeString(unrelated.resolve("level.dat"),"x");assertEquals(1,m.recoverOwnedWorlds().size());assertFalse(Files.exists(owned.directory()));assertTrue(Files.exists(unrelated));}@Test void 所有情報不一致では削除しない()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();var w=m.create(p,"run");var fake=new TemporaryWorldManager.OwnedWorld(w.worldName(),w.mapId(),w.purpose(),"wrong",w.directory());assertThrows(MapIoException.class,()->m.delete(fake));assertTrue(Files.exists(w.directory()));}
@Test void startupRecovery中は新規作成を拒否し起動前残骸だけ回収する()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();var stale=m.create(p,"setup");m.prepareStartupRecovery();CountDownLatch snapshot=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService executor=Executors.newSingleThreadExecutor();Future<?> recovery=executor.submit(()->m.recoverPreparedWorlds(()->{snapshot.countDown();try{release.await();}catch(InterruptedException e){throw new RuntimeException(e);}}));assertTrue(snapshot.await(2,TimeUnit.SECONDS));assertEquals("WORLD_RECOVERY_IN_PROGRESS",assertThrows(MapIoException.class,()->m.create(p,"run")).code());release.countDown();recovery.get(2,TimeUnit.SECONDS);executor.shutdownNow();assertFalse(Files.exists(stale.directory()));var fresh=m.create(p,"run");assertTrue(Files.exists(fresh.directory()));}
@Test void startupRecovery失敗を警告し新規作成を禁止する()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();m.prepareStartupRecovery();assertThrows(MapIoException.class,()->m.recoverPreparedWorlds(()->{throw new IllegalStateException("test");}));assertTrue(m.startupRecoveryWarning().isPresent());assertEquals("WORLD_RECOVERY",assertThrows(MapIoException.class,()->m.create(p,"setup")).code());}
@Test void 所有marker破損は起動時HardRecovery失敗として保持する()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();var world=m.create(p,"run",UUID.randomUUID().toString());Files.writeString(world.directory().resolve(".orushio-world-owner"),"broken");m.prepareStartupRecovery();assertThrows(MapIoException.class,m::recoverPreparedWorlds);assertTrue(m.recoveryRequired());assertTrue(Files.exists(world.directory()));}
@Test void activeSession破損時は全runWorldを保護しsetup残骸だけ回収する()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();var run=m.create(p,"run",UUID.randomUUID().toString());var setup=m.create(p,"setup");m.prepareStartupRecovery("",true);m.recoverPreparedWorlds();assertTrue(Files.exists(run.directory()));assertFalse(Files.exists(setup.directory()));}
@Test void setup不整合時はsetupWorldを保護しrun残骸と混同しない()throws Exception{MapProfile p=profile();TemporaryWorldManager m=manager();var setup=m.create(p,"setup",UUID.randomUUID().toString());var run=m.create(p,"run",UUID.randomUUID().toString());m.prepareStartupRecovery("",false,true);m.recoverPreparedWorlds();assertTrue(Files.exists(setup.directory()));assertFalse(Files.exists(run.directory()));}
private TemporaryWorldManager manager(){return new TemporaryWorldManager(temp.resolve("maps"),temp.resolve("worlds"));}private MapProfile profile()throws Exception{MapProfile p=MapProfileTest.empty("a");Path dir=temp.resolve("maps/a/template");Files.createDirectories(dir);Files.writeString(dir.resolve("level.dat"),"original");return p;}}
